class Solution:

	def getHeight(self, root):
		if not root:
			return 0
		return root.height

	def leftrotate(self, root):
		node = root.right
		temp = node.left
		node.left = root
		root.right = temp
		root.height = 1 + max(self.getHeight(root.left), self.getHeight(temp))
		node.height = 1 + max(self.getHeight(root), self.getHeight(node.right))
		return node

	def rightrotate(self, root):
		node = root.left
		temp = node.right
		node.right = root
		root.left = temp
		root.height = 1 + max(self.getHeight(root.right), self.getHeight(temp))
		node.height = 1 + max(self.getHeight(root), self.getHeight(node.left))
		return node

	def insertToAVL(self, root, key):
		if not root:
			return Node(key)
		if key < root.data:
			root.left = self.insertToAVL(root.left, key)
		elif key > root.data:
			root.right = self.insertToAVL(root.right, key)
		root.height = 1 + max(self.getHeight(root.left), self.getHeight(root.right))
		balance = self.getHeight(root.left) - self.getHeight(root.right)
		if balance > 1 and key < root.left.data:
			return self.rightrotate(root)
		if balance > 1 and key > root.left.data:
			root.left = self.leftrotate(root.left)
			return self.rightrotate(root)
		if balance < -1 and key > root.right.data:
			return self.leftrotate(root)
		if balance < -1 and key < root.right.data:
			root.right = self.rightrotate(root.right)
			return self.leftrotate(root)
		return root
